74	    /** Dedicated audit trail for owner-lifecycle side effects. */
75	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
76	
77	    /** Dedicated trail for the welcome notification enqueued on successful create. */
78	    private static final Logger NOTIFY = LoggerFactory.getLogger("NOTIFY");
79	
80	    /**
81	     * Monotonically increasing sequence stamped onto each {@code OWNER_CREATED} audit
82	     * event, so consumers can order and de-duplicate events across the lifetime of the
83	     * application. Shared across all creates; never reset.
84	     */
85	    private static final AtomicInteger CREATE_SEQUENCE = new AtomicInteger();
86	
87	    /** Serializer for the structured audit event; records serialize by their components. */
88	    private static final ObjectMapper AUDIT_MAPPER = JsonMapper.builder().build();
89	
90	    /**
91	     * Immutable structured audit event emitted on owner creation. Its component order
92	     * ({@code schemaVersion}, {@code seq}, {@code ownerId}, {@code memberId},
93	     * {@code membershipLevel}, {@code event}) is also the field order of the serialized
94	     * JSON. The event is at schema version 2, carrying an explicit {@code schemaVersion}
95	     * of {@code 2}; the {@code memberId} slot carries the owner's primary identifier,
96	     * recomputed from the version-2 identity.
97	     */
98	    private record OwnerCreatedEvent(int schemaVersion, int seq, Integer ownerId, String memberId,
99	                                     Integer membershipLevel, String event) {
100	    }
101	
102	    /** Schema version of the structured {@code OWNER_CREATED} audit event. */
103	    private static final int AUDIT_EVENT_SCHEMA_VERSION = 2;
104	
105	    /** Email domains from disposable/throwaway providers, rejected on create. */
106	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
107	        "mailinator.com", "tempmail.com", "guerrillamail.com");
