162	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
163	    @Override
164	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
165	        // Idempotent create: if this request carries an 'Idempotency-Key' we have already
166	        // seen, return the owner originally created under it (200) rather than creating a
167	        // duplicate. The key is remembered only after a successful create below.
168	        String idempotencyKey = currentIdempotencyKey();
169	        if (idempotencyKey != null) {
170	            Integer existingId = idempotentCreates.get(idempotencyKey);
171	            if (existingId != null) {
172	                Owner existingOwner = this.clinicService.findOwnerById(existingId);
173	                if (existingOwner != null) {
174	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existingOwner), HttpStatus.OK);
175	                }
176	            }
177	        }
178	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
179	        if (normalizedTelephone == null) {
180	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The telephone number is invalid");
181	        }
182	        if (isDisposableEmailDomain(ownerFieldsDto.getEmail())) {
183	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Disposable email domains are not accepted");
184	        }
185	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
186	        // The owner must supply an address in EITHER form: a non-blank structured
187	        // 'addressLine1' or the flat 'address'. getAddress() prefers the structured
188	        // fields (composing line 1 with an optional line 2) and falls back to the flat
189	        // value; a blank result means neither form was provided. The composed value is
190	        // written back so the persisted flat 'address' stays consistent with it.
191	        String composedAddress = owner.getAddress();
192	        if (composedAddress == null || composedAddress.isBlank()) {
193	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "An address must be supplied");
194	        }
195	        owner.setAddress(composedAddress);
196	        owner.setTelephone(normalizedTelephone);
197	        if (!owner.isPostcodeValidForCity()) {
198	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The postcode is not valid for the city");
199	        }
200	        // The household id is deterministic: it is derived purely from the owner's
201	        // (last name, postcode), so every owner at the same last name and postcode resolves
202	        // to the same value. It is assigned up front, before any duplicate detection, so the
203	        // identity key and the household check below both key off it.
204	        owner.setHouseholdId(householdId(owner));
205	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
206	        // Consolidated hard-duplicate detection: reject only when the new owner's WHOLE
207	        // identityKey (the SHA-256 over normalizedTelephone|lowerEmail|soundex(lastName))
208	        // equals an existing owner's. Because the telephone is part of the key, two owners
209	        // sharing only a last name and postcode differ here whenever their telephone or email
210	        // differs, and so are both allowed (the second is surfaced as a soft match below). This
211	        // single identity key is now the only 409 duplicate check — the former separate
212	        // household-duplicate block keyed on the computed household id no longer applies.
213	        String identityKey = owner.getIdentityKey();
214	        if (this.clinicService.findAllOwners().stream()
215	            .filter(existing -> !existing.isDeleted())
216	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
217	            throw new ResponseStatusException(HttpStatus.CONFLICT, "An owner with the same identity already exists");
218	        }
219	        // The household id is still computed for household-size and membership-level purposes,
220	        // but sharing it no longer rejects the create.
221	        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
222	        long ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
223	        if (ownersInCity >= 50) {
224	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The city has reached its owner capacity");
225	        }
226	        boolean capacityWarning = ownersInCity >= 40 && ownersInCity <= 49;
227	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
228	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The registration date must not be in the future");
229	        }
230	        LocalDate effectiveDate =
231	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
232	        LocalDate registrationDate = toBusinessDay(effectiveDate);
233	        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
234	        if (ownersRegisteredToday >= 100) {
235	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS, "The daily owner registration limit has been reached");
236	        }
237	        boolean bulkSignupWarning = ownersRegisteredToday > 80;
238	        HttpHeaders headers = new HttpHeaders();
239	        owner.setRegistrationDate(registrationDate);
240	        owner.setMemberId(memberId(owner));
241	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
242	        owner.setBulkSignupWarning(bulkSignupWarning);
243	        owner.setCapacityWarning(capacityWarning);
244	        // The household size (an input to the membership computation) keys off the computed
245	        // household id: this owner plus everyone already sharing it.
246	        owner.setHouseholdSize(householdMembers.size() + 1);
247	        // Level ceiling: a new owner joining a household they did not explicitly declare
248	        // may not out-rank the household. Cap the derived membership level at one above the
249	        // current maximum among the existing household members; with no existing member no
250	        // cap applies.
251	        if (!sharesHousehold && !householdMembers.isEmpty()) {
252	            int maxHouseholdLevel = householdMembers.stream()
253	                .mapToInt(Owner::getMembershipLevel)
254	                .max()
255	                .orElse(0);
256	            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
257	        }
258	        // Soft-match ("possible duplicate"): a declared household member is not a suspected
259	        // duplicate, so only a non-declared create is scored. A non-declared owner whose
260	        // identity key differs from an existing owner's but whose last name (by Soundex) and
261	        // postcode match is flagged here as a possible duplicate rather than rejected.
262	        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
263	        owner.setPossibleDuplicate(possibleDuplicate != null);
264	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
265	        this.clinicService.saveOwner(owner);
266	        if (idempotencyKey != null) {
267	            idempotentCreates.put(idempotencyKey, owner.getId());
268	        }
269	        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
270	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
271	        emitOwnerCreatedEvent(owner);
272	        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
273	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
274	        headers.setLocation(UriComponentsBuilder.newInstance()
275	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
276	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
277	    }
