281	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
282	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
283	        if (currentOwner == null) {
284	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
285	        }
286	        String normalizedTelephone = normalizeTelephone(ownerFieldsDto.getTelephone());
287	        if (normalizedTelephone == null) {
288	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The telephone number is invalid");
289	        }
290	        currentOwner.setAddress(ownerFieldsDto.getAddress());
291	        currentOwner.setCity(ownerFieldsDto.getCity());
292	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
293	        currentOwner.setLastName(ownerFieldsDto.getLastName());
294	        currentOwner.setTelephone(normalizedTelephone);
295	        currentOwner.setEmail(ownerFieldsDto.getEmail());
296	        this.clinicService.saveOwner(currentOwner);
297	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
298	    }
