301	    @Transactional
302	    @Override
303	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
304	        Owner owner = this.clinicService.findOwnerById(ownerId);
305	        if (owner == null) {
306	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
307	        }
308	        // Soft-delete: retain the row and flag it deleted rather than removing it. The owner
309	        // remains readable via GET, and is subsequently ignored by the create endpoint's
310	        // duplicate and identity checks.
311	        owner.setDeleted(true);
312	        this.clinicService.saveOwner(owner);
313	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
314	    }
