368	    /**
369	     * Normalize a telephone number to E.164 form. Spaces, dashes and brackets are
370	     * stripped. When a leading {@code '+'} and country code are present they are kept;
371	     * otherwise country code {@code '+61'} is assumed and a single leading {@code '0'}
372	     * is dropped from the national digits. The result must be a {@code '+'} followed
373	     * by 8 to 15 digits, and is returned as {@code +<digits>}; otherwise {@code null}
374	     * is returned to signal a bad request.
375	     */
376	    /**
377	     * Build the member id for a newly created owner, formatted
378	     * {@code '<REGION><FY><HASH8><CHK>'}: {@code REGION} is the region derived from the
379	     * owner's postcode (falling back to the city, or {@code 'UNKNOWN'}, via the same
380	     * derivation the locality uses); {@code FY} is the two-digit fiscal year derived from
381	     * the (business-day-adjusted) registration date; {@code HASH8} is the first eight
382	     * upper-case hex characters of the SHA-256 of the owner's normalized telephone
383	     * concatenated with its last name (the same hash used by the region-and-hash
384	     * identity); and {@code CHK} is a single Luhn check digit computed over the digits of
385	     * {@code <REGION><FY><HASH8>}. On the rare collision with an existing owner's member
386	     * id a {@code '-<n>'} suffix is appended.
387	     */
388	    private String memberId(Owner owner) {
389	        String base = memberIdBase(owner);
390	        java.util.Set<String> existing = this.clinicService.findAllOwners().stream()
391	            .map(Owner::getMemberId)
392	            .filter(java.util.Objects::nonNull)
393	            .collect(java.util.stream.Collectors.toSet());
394	        if (!existing.contains(base)) {
395	            return base;
396	        }
397	        int n = 2;
398	        while (existing.contains(base + "-" + n)) {
399	            n++;
400	        }
401	        return base + "-" + n;
402	    }
403	
404	    /**
405	     * Build the collision-free base of an owner's member id: {@code <REGION><FY><HASH8>}
406	     * followed by its single Luhn check digit. {@code FY} is the two-digit fiscal year
407	     * taken from {@link Owner#getFiscalYear()} (its {@code 'FY'} prefix stripped), which
408	     * is set by the time the member id is assigned.
409	     */
410	    private String memberIdBase(Owner owner) {
411	        String region = owner.identityRegionCode();
412	        String fiscalYear = owner.getFiscalYear();
413	        String fy = fiscalYear == null ? "" : fiscalYear.substring(2);
414	        String hash8 = memberIdHash(owner.getTelephone(), owner.getLastName());
415	        String core = region + fy + hash8;
416	        return core + luhnCheckDigit(core);
417	    }
418	
419	    /**
420	     * Compute a single Luhn check digit (0-9) over the digits contained in {@code s};
421	     * non-digit characters are ignored and the rightmost digit is doubled first,
422	     * following the standard Luhn algorithm.
423	     */
424	    private int luhnCheckDigit(String s) {
425	        int sum = 0;
426	        boolean doubleDigit = true;
427	        for (int i = s.length() - 1; i >= 0; i--) {
428	            char c = s.charAt(i);
429	            if (c < '0' || c > '9') {
430	                continue;
431	            }
432	            int digit = c - '0';
433	            if (doubleDigit) {
434	                digit *= 2;
435	                if (digit > 9) {
436	                    digit -= 9;
437	                }
438	            }
439	            sum += digit;
440	            doubleDigit = !doubleDigit;
441	        }
442	        return (10 - (sum % 10)) % 10;
443	    }
444	
445	    /**
446	     * Emit the immutable structured {@code OWNER_CREATED} audit event for a freshly
447	     * created owner: a schema-version-2 JSON object {@code {schemaVersion, seq, ownerId,
448	     * memberId, membershipLevel, event}} logged to the dedicated {@code AUDIT} trail
449	     * alongside the human-readable audit line. Each event is stamped with the next value
450	     * of the shared monotonic sequence, and carries the owner's current primary identifier
451	     * (the version-2 member id).
452	     */
453	    private void emitOwnerCreatedEvent(Owner owner) {
454	        OwnerCreatedEvent event = new OwnerCreatedEvent(
455	            AUDIT_EVENT_SCHEMA_VERSION,
456	            CREATE_SEQUENCE.incrementAndGet(),
457	            owner.getId(),
458	            primaryIdentifier(owner),
459	            owner.getMembershipLevel(),
460	            "OWNER_CREATED");
461	        AUDIT.info(AUDIT_MAPPER.writeValueAsString(event));
462	    }
463	
464	    /**
465	     * The owner's primary identifier, as carried by the structured audit event: the
466	     * unified member id.
467	     */
468	    private String primaryIdentifier(Owner owner) {
469	        return owner.getMemberId();
470	    }
471	
472	    /**
473	     * Compute the {@code HASH8} portion of a member id: the first eight upper-case
474	     * hex characters of the SHA-256 digest of {@code telephone + lastName} (each
475	     * treated as empty when {@code null}), already in their normalized forms.
476	     */
477	    private String memberIdHash(String telephone, String lastName) {
478	        String key = (telephone == null ? "" : telephone) + (lastName == null ? "" : lastName);
479	        try {
480	            byte[] digest = MessageDigest.getInstance("SHA-256")
481	                .digest(key.getBytes(StandardCharsets.UTF_8));
482	            StringBuilder sb = new StringBuilder();
483	            for (int i = 0; i < 4; i++) {
484	                sb.append(String.format("%02X", digest[i]));
485	            }
486	            return sb.toString();
487	        }
488	        catch (NoSuchAlgorithmException e) {
489	            throw new IllegalStateException(e);
490	        }
491	    }
492	
493	    /**
494	     * Count the existing owners whose city matches the given one, compared after
495	     * collapsing whitespace and lower-casing. Used to enforce the per-city capacity
496	     * cap: a city that already holds this many owners is at capacity.
497	     */
498	    private long countOwnersInCity(String city) {
499	        String normalizedCity = normalizeForHousehold(city);
500	        return this.clinicService.findAllOwners().stream()
501	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(normalizedCity))
502	            .count();
503	    }
504	
505	    /**
506	     * Count the existing owners whose registration date falls on the given day. Used to
507	     * enforce the per-day create limit: once this many owners have been registered today,
508	     * the day is at capacity and further creates are rejected.
509	     */
510	    private long countOwnersRegisteredOn(LocalDate day) {
511	        return this.clinicService.findAllOwners().stream()
512	            .filter(existing -> day.equals(existing.getRegistrationDate()))
513	            .count();
514	    }
515	
516	    /**
517	     * The fixed public holidays that the business-day roll skips. A registration date
518	     * landing on one of these is treated like a weekend and advanced to the next
519	     * non-holiday business day.
520	     */
521	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
522	        LocalDate.parse("2026-01-01"),
523	        LocalDate.parse("2026-01-26"),
524	        LocalDate.parse("2026-04-25"),
525	        LocalDate.parse("2026-12-25"),
526	        LocalDate.parse("2026-12-28"));
527	
528	    /**
529	     * Roll a registration date forward to the next business day: a date falling on a
530	     * Saturday, Sunday or listed public holiday is advanced one day at a time until it
531	     * lands on a non-holiday weekday, while a plain weekday is returned unchanged.
532	     */
533	    private LocalDate toBusinessDay(LocalDate date) {
534	        while (isWeekend(date) || PUBLIC_HOLIDAYS.contains(date)) {
535	            date = date.plusDays(1);
536	        }
537	        return date;
538	    }
539	
540	    private static boolean isWeekend(LocalDate date) {
541	        DayOfWeek dayOfWeek = date.getDayOfWeek();
542	        return dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY;
543	    }
544	
545	    /**
546	     * Find the existing owners that already belong to the same household as the given
547	     * computed household id. Because the household id is derived deterministically from
548	     * the owner's (last name, postcode), this is exactly the set of other owners sharing
549	     * that last name and postcode.
550	     */
551	    private List<Owner> findHouseholdMembers(String householdId) {
552	        if (householdId == null) {
553	            return List.of();
554	        }
555	        return this.clinicService.findAllOwners().stream()
556	            .filter(existing -> !existing.isDeleted())
557	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
558	            .toList();
559	    }
560	
561	    /**
562	     * Find an existing owner that this new owner softly duplicates: one whose last name has
563	     * the same Soundex code and whose postcode matches, but whose whole identity key differs
564	     * (an equal identity key is a hard duplicate, already rejected above with 409). Returns
565	     * the lowest-id such owner, or {@code null} when the new owner has no postcode or no soft
566	     * match exists. Owners flagged deleted are ignored.
567	     */
568	    private Owner findPossibleDuplicate(Owner owner) {
569	        String postcode = owner.getPostcode();
570	        if (postcode == null) {
571	            return null;
572	        }
573	        String soundex = Owner.soundex(owner.getLastName());
574	        String identityKey = owner.getIdentityKey();
575	        return this.clinicService.findAllOwners().stream()
576	            .filter(existing -> !existing.isDeleted())
577	            .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex)
578	                && postcode.equals(existing.getPostcode())
579	                && !identityKey.equals(existing.getIdentityKey()))
580	            .min(java.util.Comparator.comparing(Owner::getId))
581	            .orElse(null);
582	    }
583	
584	    /**
585	     * Count the existing owners that already share both the given first and last
586	     * name, compared case-insensitively. Used to populate an owner's namesake count
587	     * at creation time, reflecting how many owners with the same name existed before
588	     * this one was created.
589	     */
590	    private int countNamesakes(String firstName, String lastName) {
591	        String normalizedFirstName = normalizeName(firstName);
592	        String normalizedLastName = normalizeName(lastName);
593	        return (int) this.clinicService.findAllOwners().stream()
594	            .filter(existing -> normalizeName(existing.getFirstName()).equals(normalizedFirstName)
595	                && normalizeName(existing.getLastName()).equals(normalizedLastName))
596	            .count();
597	    }
598	
599	    private String normalizeName(String value) {
600	        return value == null ? "" : value.toLowerCase(Locale.ROOT);
601	    }
602	
603	    /**
604	     * Build the deterministic identifier shared by all owners of one household: the first
605	     * 12 hex characters of the SHA-256 digest of
606	     * {@code identityRegionCode + '|' + normalizedLastName + '|' + postcode}. Under version 2
607	     * of the owner identity the digest input is prefixed with the version-2 region code
608	     * ({@link Owner#identityRegionCode()}, carrying the fixed {@code 'V2'} tag) so the value
609	     * differs from its version-1 form. Because that region derives from the same
610	     * (postcode, city) and the other parts depend only on the (last name, postcode) pair,
611	     * every owner at the same last name and postcode still resolves to the same value
612	     * regardless of creation order.
613	     */
614	    private String householdId(Owner owner) {
615	        String postcode = owner.getPostcode();
616	        String key = owner.identityRegionCode() + "|" + normalizeForHousehold(owner.getLastName())
617	            + "|" + (postcode == null ? "" : postcode);
618	        try {
619	            byte[] digest = MessageDigest.getInstance("SHA-256")
620	                .digest(key.getBytes(StandardCharsets.UTF_8));
621	            StringBuilder sb = new StringBuilder();
622	            for (int i = 0; i < 6; i++) {
623	                sb.append(String.format("%02x", digest[i]));
624	            }
625	            return sb.toString();
626	        }
627	        catch (NoSuchAlgorithmException e) {
628	            throw new IllegalStateException(e);
629	        }
630	    }
631	
632	    private String normalizeForHousehold(String value) {
633	        if (value == null) {
634	            return "";
635	        }
636	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
637	    }
638	
639	    /** True when the email's domain is on the disposable-provider blocklist. */
640	    private boolean isDisposableEmailDomain(String email) {
641	        if (email == null) {
642	            return false;
643	        }
644	        int at = email.lastIndexOf('@');
645	        if (at < 0 || at == email.length() - 1) {
646	            return false;
647	        }
648	        String domain = email.substring(at + 1).trim().toLowerCase(Locale.ROOT);
649	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
650	    }
651	
652	    /**
653	     * Read the {@code Idempotency-Key} header from the current request, or {@code null}
654	     * when it is absent or blank (the generated API signature does not expose it, so it is
655	     * pulled from the bound request attributes).
656	     */
657	    private String currentIdempotencyKey() {
658	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attributes)) {
659	            return null;
660	        }
661	        String key = attributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
662	        return (key == null || key.isBlank()) ? null : key;
663	    }
664	
665	    private String normalizeTelephone(String telephone) {
666	        if (telephone == null) {
667	            return null;
668	        }
669	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
670	        String digits;
671	        if (cleaned.startsWith("+")) {
672	            digits = cleaned.substring(1);
673	        } else {
674	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
675	            digits = "61" + national;
676	        }
677	        if (!digits.matches("[0-9]{8,15}")) {
678	            return null;
679	        }
680	        if (!hasValidNationalLength(digits)) {
681	            return null;
682	        }
683	        return "+" + digits;
684	    }
685	
686	    /**
687	     * Validate the national-number length of an E.164 number (the digits, without the
688	     * leading {@code '+'}) against its country code. Australia ({@code '+61'}) requires
689	     * exactly 9 national digits and North America ({@code '+1'}) exactly 10; country
690	     * codes without a known rule are accepted as-is.
691	     */
692	    private boolean hasValidNationalLength(String digits) {
693	        if (digits.startsWith("61")) {
694	            return digits.length() - 2 == 9;
695	        }
696	        if (digits.startsWith("1")) {
697	            return digits.length() - 1 == 10;
698	        }
699	        return true;
700	    }
701	
702	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
703	    @Override
704	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
705	        Owner owner = this.clinicService.findOwnerById(ownerId);
706	        if (owner != null) {
707	            Pet pet = owner.getPet(petId);
708	            if (pet != null) {
709	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
710	            }
711	        }
712	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
713	    }
714	}
