268	        if (digits.length() <= countryCodeLength) {
269	            return this.telephone;
270	        }
271	        String countryCode = digits.substring(0, countryCodeLength);
272	        String national = digits.substring(countryCodeLength);
273	        StringBuilder sb = new StringBuilder("+").append(countryCode);
274	        for (int i = 0; i < national.length(); i += 3) {
275	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
276	        }
277	        return sb.toString();
278	    }
