359	     * the city has no known region, or if it is four digits falling within the
360	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
361	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
362	     */
363	    public boolean isPostcodeValidForCity() {
364	        if (this.postcode == null) {
365	            return true;
366	        }
367	        String region = CITY_REGION.get(this.city);
368	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
369	        if (range == null) {
370	            return true;
