731	    /**
732	     * Compute the American Soundex code of the given name: its first letter followed
733	     * by three digits derived from the remaining consonants (vowels act as separators,
734	     * {@code H} and {@code W} are transparent, and adjacent equal codes collapse),
735	     * zero-padded and truncated to four characters. Returns an empty string when the
736	     * name is {@code null} or holds no letters.
737	     */
738	    public static String soundex(String name) {
739	        if (name == null) {
740	            return "";
741	        }
742	        StringBuilder letters = new StringBuilder();
743	        for (int i = 0; i < name.length(); i++) {
744	            char c = name.charAt(i);
745	            if (Character.isLetter(c)) {
746	                letters.append(Character.toUpperCase(c));
747	            }
748	        }
749	        if (letters.length() == 0) {
750	            return "";
751	        }
752	        StringBuilder code = new StringBuilder();
753	        code.append(letters.charAt(0));
754	        char prevDigit = soundexDigit(letters.charAt(0));
755	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
756	            char c = letters.charAt(i);
757	            if (c == 'H' || c == 'W') {
758	                continue;
759	            }
760	            char digit = soundexDigit(c);
761	            if (digit != '0' && digit != prevDigit) {
762	                code.append(digit);
763	            }
764	            prevDigit = digit;
765	        }
766	        while (code.length() < 4) {
767	            code.append('0');
768	        }
769	        return code.toString();
770	    }
771	
772	    private static char soundexDigit(char c) {
773	        switch (c) {
774	            case 'B': case 'F': case 'P': case 'V':
775	                return '1';
776	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
777	                return '2';
778	            case 'D': case 'T':
779	                return '3';
780	            case 'L':
781	                return '4';
782	            case 'M': case 'N':
783	                return '5';
784	            case 'R':
785	                return '6';
786	            default:
787	                return '0';
788	        }
789	    }
