18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.security.access.AccessDeniedException;
34	import org.springframework.validation.BindingResult;
35	import org.springframework.validation.FieldError;
36	import org.springframework.web.bind.MethodArgumentNotValidException;
37	import org.springframework.web.bind.annotation.ControllerAdvice;
38	import org.springframework.web.bind.annotation.ExceptionHandler;
39	import org.springframework.web.bind.annotation.ResponseBody;
40	import org.springframework.web.server.ResponseStatusException;
41	
42	/**
43	 * Global Exception handler for REST controllers.
44	 * <p>
45	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
46	 *
47	 * @author Vitaliy Fedoriv
48	 * @author Alexander Dudkin
49	 */
50	@ControllerAdvice
51	public class ExceptionControllerAdvice {
52	
53	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
54	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
55	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
56	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
57	
58	    /**
59	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
60	     * class.
61	     *
62	     * @param e     Object referring to the thrown exception.
63	     * @param status HTTP response status.
64	     * @param url URL request.
65	     */
66	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
67	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
68	        problemDetail.setType(URI.create(url.toString()));
69	        problemDetail.setTitle(e.getClass().getSimpleName());
70	        problemDetail.setDetail(detail);
71	        problemDetail.setProperty("timestamp", Instant.now());
72	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
73	        return problemDetail;
74	    }
75	
76	    /**
77	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
78	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
79	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
80	     * would catch it and report an authorization failure as a 500.
81	     *
82	     * @param e The {@link AccessDeniedException} to propagate
83	     * @throws AccessDeniedException always
84	     */
85	    @ExceptionHandler(AccessDeniedException.class)
86	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
87	        throw e;
88	    }
89	
90	    /**
91	     * Handles {@link ResponseStatusException} raised by controllers to reject a request with an
92	     * explicit status (e.g. 400 Bad Request, 409 Conflict, 429 Too Many Requests). The response
93	     * carries an RFC 7807 {@code application/problem+json} body with {@code type}, {@code title},
94	     * {@code status} and {@code detail}, preserving the exception's HTTP status code.
95	     *
96	     * @param e The {@link ResponseStatusException} to be handled
97	     * @param request {@link HttpServletRequest} object referring to the current request.
98	     * @return A {@link ResponseEntity} whose body is the problem detail and whose status matches the exception
99	     */
100	    @ExceptionHandler(ResponseStatusException.class)
101	    @ResponseBody
102	    public ResponseEntity<ProblemDetail> handleResponseStatusException(ResponseStatusException e, HttpServletRequest request) {
103	        HttpStatus status = HttpStatus.valueOf(e.getStatusCode().value());
104	        logger.warn("Request rejected with {} at {} {}: {}",
105	            status.value(),
106	            request.getMethod(),
107	            request.getRequestURI(),
108	            e.getReason());
109	        String detail = e.getReason() != null ? e.getReason() : ERROR_INVALID_REQUEST;
110	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
111	        return ResponseEntity.status(status).body(problemDetail);
112	    }
113	
114	    /**
115	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
116	     *
117	     * @param e The {@link Exception} to be handled
118	     * @param request {@link HttpServletRequest} object referring to the current request.
119	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
120	     */
121	    @ExceptionHandler(Exception.class)
122	    @ResponseBody
123	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
124	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
125	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
126	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
127	        return ResponseEntity.status(status).body(detail);
128	    }
129	
130	    /**
131	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
132	     * method returns a 404 Not Found status if an entity does not exist.
133	     *
134	     * @param e The {@link DataIntegrityViolationException} to be handled
135	     * @param request {@link HttpServletRequest} object referring to the current request.
136	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
137	     */
138	    @ExceptionHandler(DataIntegrityViolationException.class)
139	    @ResponseBody
140	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
141	        logger.warn("Data integrity violation at {} {}: {}",
142	            request.getMethod(),
143	            request.getRequestURI(),
144	            e.getMessage());
145	        logger.debug("Data integrity violation stacktrace", e);
146	        HttpStatus status = HttpStatus.NOT_FOUND;
147	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
148	        return ResponseEntity.status(status).body(detail);
149	    }
150	
151	    /**
152	     * Handles exception thrown by Bean Validation on controller methods parameters
153	     *
154	     * @param e The {@link MethodArgumentNotValidException} to be handled
155	     * @param request {@link HttpServletRequest} object referring to the current request.
156	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
157	     */
158	    @ExceptionHandler(MethodArgumentNotValidException.class)
159	    @ResponseBody
160	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
161	        HttpStatus status = HttpStatus.BAD_REQUEST;
162	        BindingErrorsResponse errors = new BindingErrorsResponse();
163	        BindingResult bindingResult = e.getBindingResult();
164	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
165	        if (bindingResult.hasErrors()) {
166	            errors.addAllErrors(bindingResult);
167	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
168	                .map(fieldError -> {
169	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
170	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
171	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
172	                        fieldError.getField(),
173	                        defaultMessage,
174	                        rejectedValue);
175	                    return new ValidationMessageDto(message)
176	                        .putAdditionalProperty("field", fieldError.getField())
177	                        .putAdditionalProperty("rejectedValue", rejectedValue)
178	                        .putAdditionalProperty("defaultMessage", defaultMessage);
179	                })
180	                .toList();
181	            logger.debug("Validation error at {} {}: {}",
182	                request.getMethod(),
183	                request.getRequestURI(),
184	                bindingResult.getFieldErrors());
185	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
186	            List<String> missingFields = bindingResult.getFieldErrors().stream()
187	                .filter(ExceptionControllerAdvice::isMissingOrBlank)
188	                .map(FieldError::getField)
189	                .distinct()
190	                .toList();
191	            detail.setProperty("errors", missingFields);
192	            return ResponseEntity.status(status).body(detail);
193	        }
194	        detail.setProperty("errors", List.<String>of());
195	        return ResponseEntity.status(status).body(detail);
196	    }
197	
198	    /**
199	     * Determines whether a field validation error was caused by the field being missing (null) or
200	     * blank (empty or whitespace-only). Used to build the {@code errors} array that lists the name
201	     * of each required owner field the client failed to supply.
202	     *
203	     * @param fieldError the rejected field error to inspect
204	     * @return {@code true} if the rejected value is {@code null} or a blank string
205	     */
206	    private static boolean isMissingOrBlank(FieldError fieldError) {
207	        Object rejectedValue = fieldError.getRejectedValue();
208	        return rejectedValue == null
209	            || (rejectedValue instanceof String value && value.isBlank());
210	    }
211	
212	}
