            .filter(existing -> !existing.isDeleted())
            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()))) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "An owner with the same identity already exists");
        }
        List<Owner> householdMembers = findHouseholdMembers(owner.getHouseholdId());
        long ownersInCity = countOwnersInCity(ownerFieldsDto.getCity());
        if (ownersInCity >= 50) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The city has reached its owner capacity");
        }
        boolean capacityWarning = ownersInCity >= 40 && ownersInCity <= 49;
        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The registration date must not be in the future");
        }
        LocalDate effectiveDate =
            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
        LocalDate registrationDate = toBusinessDay(effectiveDate);
        long ownersRegisteredToday = countOwnersRegisteredOn(registrationDate);
        if (ownersRegisteredToday >= 100) {
            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS, "The daily owner registration limit has been reached");
        }
        boolean bulkSignupWarning = ownersRegisteredToday > 80;
        HttpHeaders headers = new HttpHeaders();
        owner.setRegistrationDate(registrationDate);
        owner.setMemberId(memberId(owner));
        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
        owner.setBulkSignupWarning(bulkSignupWarning);
        owner.setCapacityWarning(capacityWarning);
        owner.setHouseholdSize(householdMembers.size() + 1);
        if (!sharesHousehold && !householdMembers.isEmpty()) {
            int maxHouseholdLevel = householdMembers.stream()
                .mapToInt(Owner::getMembershipLevel).max().orElse(0);
            owner.setMembershipLevelCap(maxHouseholdLevel + 1);
        }
        Owner possibleDuplicate = sharesHousehold ? null : findPossibleDuplicate(owner);
        owner.setPossibleDuplicate(possibleDuplicate != null);
        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
        this.clinicService.saveOwner(owner);
        if (idempotencyKey != null) {
            idempotentCreates.put(idempotencyKey, owner.getId());
        }
        AUDIT.info("owner created id={} memberId={} registrationDate={} membershipLevel={}",
            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), owner.getMembershipLevel());
        emitOwnerCreatedEvent(owner);
        NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
        headers.setLocation(UriComponentsBuilder.newInstance()
            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
    }
```

**Exact order of manual (post-Bean-Validation) checks in the controller:**
1. Idempotency-Key short-circuit → 200 if key already seen.
2. `normalizeTelephone` → 400 "The telephone number is invalid".
3. `isDisposableEmailDomain` → 400 "Disposable email domains are not accepted".
4. Map DTO→entity, then composed address blank → 400 "An address must be supplied".
5. `isPostcodeValidForCity()` → 400 "The postcode is not valid for the city".
6. Whole-identity-key duplicate → 409 "An owner with the same identity already exists".
7. City capacity ≥50 → 409 "The city has reached its owner capacity".
8. Registration date in future → 400 "The registration date must not be in the future".
9. Daily limit ≥100 → 429 "The daily owner registration limit has been reached".
10. Persist, record idempotency key, emit audit/notify, return 201 with `Location` header.

Note: the class carries method-level auth `@PreAuthorize("hasRole(@roles.OWNER_ADMIN)")` (line 162) — requires role `ROLE_OWNER_ADMIN` (see §7).

